def plan_layouts(versions, bursts, costs, budget, native_ready):
    """Jointly optimal layout of every immutable version of one case."""
    per_version = [[] for _ in versions]
    for version, repeat, addresses in bursts:
        starts = versions[version][0]
        per_version[version].append((repeat, [fib.run_index(starts, a) for a in addresses]))
    if native_ready:
        try:
            layouts = native.plan(versions, per_version, costs, budget)
            if len(layouts) == len(versions) and all(
                    check_layout(starts, hops, nodes)
                    for (starts, hops), nodes in zip(versions, layouts)):
                return layouts
        except Exception:
            layouts = None
    weights = []
    for index, (starts, _hops) in enumerate(versions):
        members = [(version, repeat, addresses)
                   for version, repeat, addresses in bursts if version == index]
        q, t = fib.interval_weights(starts, members)
        weights.append((q, t))
